from ...config import ENBConfig

from .base_cl_tool import BaseClToolInterface


class IPConnectivityInterface(BaseClToolInterface):

    def check_ip_connectivity(self, remote_ip, source_ip=None, timeout='15min', **kwargs):
        """Executes IP connectivity test in one site.

        :param string remote_ip: Remote IP address in the Site.
        :param string source_ip: Source IP address in the Site.

        :return Path(s) of collected file(s).
        :rtype list
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        timeout = self._convert_to_secs(timeout)
        config = self.command_store.get(alias).get_config()
        ne = kwargs.get('ne', config.trs_ip).strip()
        pw = kwargs.get('pw', config.pw).strip()
        params = {'remoteip': remote_ip, 'sourceip': source_ip, 'ne': ne, 'pw': pw, 'timeout': timeout}
        nolog = config.nolog if kwargs.get('nolog') is None else kwargs.get('nolog')
        flags = ['nolog'] if nolog else []
        return self._execute_cl_tool_operation(alias=alias, timeout=timeout, operation='iptest', params=params, trs_ip=ne, flags=flags)
